//! OKLab / OKLCH conversions (Björn Ottosson, 2020).
//!
//! Surfaces for the dark and light variants are generated by walking
//! *perceptual* lightness rather than HSL lightness, so the steps look even and
//! a hue stays stable while it is darkened. HSL would make saturated blues
//! collapse to near-black much faster than yellows, which produced muddy
//! backgrounds in the prototype.
//!
//! Chroma is reduced rather than clipped when a colour falls outside sRGB,
//! because clamping channels shifts hue and would break "the theme matches the
//! wallpaper" for saturated wallpapers.

use crate::color::Rgb;

/// A colour in OKLab: `l` is perceptual lightness in `0.0..=1.0`, `a` and `b`
/// are the opponent axes (roughly green/red and blue/yellow).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Oklab {
    pub l: f32,
    pub a: f32,
    pub b: f32,
}

/// A colour in OKLCH: perceptual lightness, chroma and hue.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Oklch {
    pub l: f32,
    pub c: f32,
    /// Hue in degrees, `0.0..360.0`.
    pub h: f32,
}

fn srgb_to_linear(c: u8) -> f32 {
    let s = c as f32 / 255.0;
    if s <= 0.040_45 {
        s / 12.92
    } else {
        ((s + 0.055) / 1.055).powf(2.4)
    }
}

fn linear_to_srgb(v: f32) -> f32 {
    if v <= 0.003_130_8 {
        12.92 * v
    } else {
        1.055 * v.powf(1.0 / 2.4) - 0.055
    }
}

impl Oklab {
    #[must_use]
    pub fn from_rgb(rgb: Rgb) -> Self {
        let r = srgb_to_linear(rgb.r);
        let g = srgb_to_linear(rgb.g);
        let b = srgb_to_linear(rgb.b);

        let l = (0.412_221_47 * r + 0.536_332_55 * g + 0.051_445_99 * b).cbrt();
        let m = (0.211_903_5 * r + 0.680_699_5 * g + 0.107_396_96 * b).cbrt();
        let s = (0.088_302_46 * r + 0.281_718_84 * g + 0.629_978_7 * b).cbrt();

        Self {
            l: 0.210_454_26 * l + 0.793_617_8 * m - 0.004_072_047 * s,
            a: 1.977_998_5 * l - 2.428_592_2 * m + 0.450_593_7 * s,
            b: 0.025_904_037 * l + 0.782_771_77 * m - 0.808_675_77 * s,
        }
    }

    /// Convert back to sRGB. Returns `None` when the colour is outside the sRGB
    /// gamut, so callers can decide between reducing chroma and accepting it.
    #[must_use]
    pub fn try_to_rgb(self) -> Option<Rgb> {
        let l_ = self.l + 0.396_337_78 * self.a + 0.215_803_76 * self.b;
        let m_ = self.l - 0.105_561_346 * self.a - 0.063_854_17 * self.b;
        let s_ = self.l - 0.089_484_18 * self.a - 1.291_485_5 * self.b;

        let l = l_ * l_ * l_;
        let m = m_ * m_ * m_;
        let s = s_ * s_ * s_;

        let r = 4.076_741_7 * l - 3.307_711_6 * m + 0.230_969_94 * s;
        let g = -1.268_438 * l + 2.609_757_4 * m - 0.341_319_38 * s;
        let b = -0.004_196_086_3 * l - 0.703_418_6 * m + 1.707_614_7 * s;

        // A small epsilon keeps colours that are a rounding error outside the
        // cube from being rejected.
        const EPS: f32 = 1e-5;
        if !(-EPS..=1.0 + EPS).contains(&r)
            || !(-EPS..=1.0 + EPS).contains(&g)
            || !(-EPS..=1.0 + EPS).contains(&b)
        {
            return None;
        }

        let to_u8 = |v: f32| {
            (linear_to_srgb(v.clamp(0.0, 1.0)) * 255.0)
                .round()
                .clamp(0.0, 255.0) as u8
        };
        Some(Rgb::rgb(to_u8(r), to_u8(g), to_u8(b)))
    }

    #[must_use]
    pub fn to_oklch(self) -> Oklch {
        Oklch {
            l: self.l,
            c: (self.a * self.a + self.b * self.b).sqrt(),
            h: self.b.atan2(self.a).to_degrees().rem_euclid(360.0),
        }
    }
}

impl Oklch {
    #[must_use]
    pub fn to_oklab(self) -> Oklab {
        let rad = self.h.to_radians();
        Oklab {
            l: self.l,
            a: self.c * rad.cos(),
            b: self.c * rad.sin(),
        }
    }

    pub fn from_rgb(rgb: Rgb) -> Self {
        Oklab::from_rgb(rgb).to_oklch()
    }

    /// Convert to sRGB, reducing chroma in small steps until the colour is
    /// representable. This is the documented "gamut mapping by chroma clamp"
    /// approximation: it preserves lightness and hue exactly.
    #[must_use]
    pub fn to_rgb(self) -> Rgb {
        if let Some(rgb) = self.to_oklab().try_to_rgb() {
            return rgb;
        }
        // Binary search the largest in-gamut chroma below the requested one.
        let mut low = 0.0_f32;
        let mut high = self.c;
        let mut best = Oklch { c: 0.0, ..self }.to_oklab().try_to_rgb();
        for _ in 0..24 {
            let mid = (low + high) / 2.0;
            match (Oklch { c: mid, ..self }).to_oklab().try_to_rgb() {
                Some(rgb) => {
                    best = Some(rgb);
                    low = mid;
                }
                None => high = mid,
            }
        }
        // A fully desaturated colour at a valid lightness is always in gamut,
        // but stay defensive in case of NaN inputs.
        best.unwrap_or_else(|| {
            let v = (self.l.clamp(0.0, 1.0) * 255.0).round() as u8;
            Rgb::rgb(v, v, v)
        })
    }

    /// Copy with a different perceptual lightness and chroma.
    #[must_use]
    pub fn with(self, l: f32, c: f32) -> Self {
        Oklch {
            l: l.clamp(0.0, 1.0),
            c: c.max(0.0),
            h: self.h,
        }
    }
}

/// How "dark" a colour is perceptually, in `0.0..=1.0`.
pub fn perceived_lightness(rgb: Rgb) -> f32 {
    Oklab::from_rgb(rgb).l
}

/// The perceptual lightness of a colour when composited over `background`.
pub fn composited_lightness(foreground: Rgb, background: Rgb) -> f32 {
    perceived_lightness(foreground.over(background))
}

#[cfg(test)]
mod tests {
    // Test modules use deliberate idioms clippy flags by default: exhaustive
    // `other => panic!()` guards so a new variant cannot pass silently, and
    // `assert!(x.is_empty())` for readability.
    #![allow(
        clippy::single_match_else,
        clippy::wildcard_in_or_patterns,
        clippy::bool_assert_comparison,
        clippy::struct_excessive_bools,
        clippy::match_same_arms,
        clippy::needless_borrow,
        clippy::map_unwrap_or,
        clippy::unnecessary_wraps,
        clippy::redundant_closure,
        clippy::unused_unit,
        clippy::items_after_statements,
        clippy::needless_borrows_for_generic_args,
        clippy::ptr_arg
    )]
    use super::*;

    fn close(a: f32, b: f32, eps: f32) -> bool {
        (a - b).abs() <= eps
    }

    #[test]
    fn known_oklab_reference_values() {
        // Reference values from Ottosson's published test vectors.
        let white = Oklab::from_rgb(Rgb::rgb(255, 255, 255));
        assert!(
            close(white.l, 1.0, 0.005) && close(white.a, 0.0, 0.005) && close(white.b, 0.0, 0.005)
        );

        let black = Oklab::from_rgb(Rgb::rgb(0, 0, 0));
        assert!(
            close(black.l, 0.0, 0.001) && close(black.a, 0.0, 0.001) && close(black.b, 0.0, 0.001)
        );

        let red = Oklab::from_rgb(Rgb::rgb(255, 0, 0));
        assert!(close(red.l, 0.627_96, 0.005), "red L was {}", red.l);
        assert!(close(red.a, 0.224_86, 0.005), "red a was {}", red.a);
        assert!(close(red.b, 0.125_85, 0.005), "red b was {}", red.b);
    }

    #[test]
    fn round_trip_within_one_step_for_all_channels() {
        for hex in [
            "#000000", "#ffffff", "#5f6fdd", "#3ddc97", "#ff0000", "#00ff00", "#0000ff", "#808080",
            "#123456", "#f0c0a0",
        ] {
            let rgb = Rgb::from_hex(hex).unwrap();
            let back = Oklch::from_rgb(rgb).to_rgb();
            assert!(
                rgb.channel_distance(back) <= 1,
                "{hex} -> {} (max channel delta {})",
                back,
                rgb.channel_distance(back)
            );
        }
    }

    #[test]
    fn out_of_gamut_colours_reduce_chroma_not_hue() {
        let vivid = Oklch {
            l: 0.7,
            c: 0.4,
            h: 150.0,
        };
        let rgb = vivid.to_rgb();
        let back = Oklch::from_rgb(rgb);
        assert!((back.h - 150.0).abs() < 3.0, "hue drifted to {}", back.h);
        assert!(
            back.c < 0.4,
            "chroma should have been reduced, got {}",
            back.c
        );
        assert!(
            (back.l - 0.7).abs() < 0.03,
            "lightness drifted to {}",
            back.l
        );
    }

    #[test]
    fn lightness_ordering_matches_perception() {
        let samples = ["#000000", "#202020", "#808080", "#c0c0c0", "#ffffff"];
        let mut previous = -1.0;
        for hex in samples {
            let l = perceived_lightness(Rgb::from_hex(hex).unwrap());
            assert!(l > previous, "{hex} lightness {l} not above {previous}");
            previous = l;
        }
    }

    #[test]
    fn equal_lightness_greys_map_to_zero_chroma() {
        for hex in ["#ffffff", "#808080", "#101010"] {
            let lch = Oklch::from_rgb(Rgb::from_hex(hex).unwrap());
            assert!(lch.c < 0.002, "{hex} had chroma {}", lch.c);
        }
    }
}
